ep_file_validate.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let fileId = str(body.fileId ?? req.fileId ?? "").trim();

let files = vdb.collection("file_records");
let rows = [];
if (fileId != "") {
  let lookup = files.find({fileId: {$eq: fileId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = files.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No file record is available to validate"};
}

let file = rows[0];
fileId = str(file.fileId ?? fileId).trim();
let metadata = type(file.metadata) == "object" ? file.metadata : {};
let security = type(metadata.security) == "object" ? metadata.security : {};
let policy = type(security.policy) == "object" ? security.policy : {};
let checks = [];
let issues = [];

let ownerOk = str(file.owner ?? "").trim() != "";
checks.add({name: "owner_present", ok: ownerOk});
if (!ownerOk) {
  issues.add("owner_missing");
}

let securityOk = type(security) == "object" && leng(security.keys()) > 0;
checks.add({name: "security_present", ok: securityOk});
if (!securityOk) {
  issues.add("security_block_missing");
}

let classification = str(policy.classification ?? "").trim();
let classificationOk = classification != "";
checks.add({name: "classification_present", ok: classificationOk});
if (!classificationOk) {
  issues.add("classification_missing");
}

let retentionDays = policy.retentionDays ?? 0;
if (retentionDays == "") {
  retentionDays = 0;
}
let retentionOk = retentionDays > 0;
checks.add({name: "retention_positive", ok: retentionOk});
if (!retentionOk) {
  issues.add("retention_days_invalid");
}

let validated = ownerOk && securityOk && classificationOk && retentionOk;
let nowTs = datetime.now().isoformat();
let validation = {
  status: validated ? "VALID" : "INVALID",
  validatedAt: nowTs,
  validatedBy: actor,
  classification: classification,
  retentionDays: retentionDays,
  issues: issues
};
let nextMetadata = {
  security: security,
  validation: validation
};

if (dryRun) {
  return {ok: true, dryRun: true, fileId: fileId, validated: validated, checks: checks, validation: validation};
}

let updateRes = files.update({fileId: {$eq: fileId}}, {metadata: nextMetadata});
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to persist validation result", fileId: fileId, result: updateRes};
}

let runs = vdb.collection("file_validation_runs");
let runId = crypto.uuid();
let runRes = runs.insert({
  runId: runId,
  fileId: fileId,
  validated: validated,
  checks: checks,
  validation: validation
});

return {ok: true, fileId: fileId, validated: validated, checks: checks, runId: runId, runRecorded: runRes.ok ?? false, validation: validation};

